# Property sanitization and normalization
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Battery-pack list merging
# ---------------------------------------------------------------------------


def _is_shadowed_pack_selector(merged: list[dict[str, Any]], idx: int) -> bool:
    """Return whether a serial-less selector entry has a real adjacent pack."""
    item = merged[idx]
    if set(item) != {FIELD_DEV_TYPE}:
        return False
    if str(item.get(FIELD_DEV_TYPE)) != str(
        SUBDEVICE_DEV_TYPE_BATTERY_PACK
    ) or looks_like_battery_pack(item, CT_METER_KEYS, BATTERY_PACK_HINT_KEYS):
        return False
    return any(
        battery_pack_serial(merged[adj_idx]) is not None
        and merged[adj_idx].get(FIELD_DEV_TYPE) == item.get(FIELD_DEV_TYPE)
        and looks_like_battery_pack(
            merged[adj_idx], CT_METER_KEYS, BATTERY_PACK_HINT_KEYS
        )
        for adj_idx in (idx - 1, idx + 1)
        if 0 <= adj_idx < len(merged)
    )


def _battery_pack_value_present(field: str, value: object) -> bool:
    """Keep opaque pack fields while requiring finite known measurements."""
    if field in {
        FIELD_BAT_SOC,
        FIELD_CELL_TEMP,
        FIELD_IN_PW,
        FIELD_OUT_PW,
        FIELD_IN_EGY,
        FIELD_OUT_EGY,
    }:
        return isinstance(value, (int, float, str)) and safe_float(value) is not None
    return value is not None


def _battery_pack_merge_update(raw_update: dict[str, Any]) -> dict[str, Any]:
    """Retain present values without treating blank serials as identities."""
    update = {
        key: value
        for key, value in raw_update.items()
        if _battery_pack_value_present(key, value)
    }
    for identity_key in (FIELD_DEVICE_SN, FIELD_DEV_SN, FIELD_SN):
        identity = update.get(identity_key)
        if identity is None or (isinstance(identity, str) and not identity.strip()):
            update.pop(identity_key, None)
    return update


def _pack_raw_identity_mapping(
    pack: Mapping[str, Any], identity_keys: tuple[str, ...]
) -> dict[str, Any]:
    """Return explicit raw identity fields, excluding synthetic redaction markers."""
    identities: dict[str, Any] = {}
    for key in identity_keys:
        if key not in pack:
            continue
        value = pack[key]
        if isinstance(value, str) and value.strip() == REDACTED_VALUE:
            return {}
        identities[key] = value
    return identities


def _matching_anonymous_pack_index(
    merged: list[dict[str, Any]],
    unmatched: list[int],
    update: dict[str, Any],
    identity_keys: tuple[str, ...],
    sn: str | None,
) -> int | None:
    """Match an anonymous or corrupt-serial update against unmatched slots."""
    raw_identities = (
        _pack_raw_identity_mapping(update, identity_keys) if sn is None else {}
    )
    target_idx = next(
        (
            idx
            for idx in unmatched
            if _raw_values_equal(merged[idx], update)
            or (
                bool(raw_identities)
                and _raw_mapping_equal(
                    _pack_raw_identity_mapping(merged[idx], identity_keys),
                    raw_identities,
                )
            )
        ),
        None,
    )
    if target_idx is not None:
        unmatched.remove(target_idx)
    return target_idx


@dataclass(frozen=True, slots=True)
class _PositionalPackMatchOptions:
    """Matching rules for resolving positional battery-pack slots."""

    identity_keys: tuple[str, ...]
    updates_count: int
    ambiguous: set[str]
    confirm_serial_slot: Callable[[int, str], bool] | None


def _positional_pack_target_index(  # ruff: ignore[too-many-return-statements]
    merged: list[dict[str, Any]],
    update_idx: int,
    update: dict[str, Any],
    options: _PositionalPackMatchOptions,
) -> int | None:
    """Resolve an unambiguous positional pack slot for anonymous or learned updates."""
    if update_idx >= len(merged):
        return None
    prior_clean = _battery_pack_merge_update(merged[update_idx])
    # Source-scoped anonymous group order is not a physical serial binding.
    if isinstance(prior_clean.get("_jackery_unbound_group_slot"), dict):
        return None
    prior_sn = battery_pack_serial(prior_clean)
    sn = battery_pack_serial(update)
    identity_set = set(options.identity_keys)
    single_slot = len(merged) == 1 and options.updates_count == 1
    if sn is None:
        if identity_set.intersection(update):
            return None
        if (prior_sn is not None and prior_sn not in options.ambiguous) or (
            single_slot and not identity_set.intersection(prior_clean)
        ):
            return update_idx
        return None
    if (
        sn in options.ambiguous
        or prior_sn is not None
        or bool(identity_set.intersection(prior_clean))
    ):
        return None
    confirmed = (
        options.confirm_serial_slot(update_idx + 1, sn)
        if options.confirm_serial_slot is not None
        else single_slot
    )
    return update_idx if confirmed else None


def merge_battery_pack_lists(
    current: object,
    updates: list[dict[str, Any]],
    *,
    allow_positional_matching: bool = True,
    select_update: Callable[[dict[str, Any], dict[str, Any], int], dict[str, Any]]
    | None = None,
    confirm_serial_slot: Callable[[int, str], bool] | None = None,
) -> list[dict[str, Any]]:
    """Merge incremental battery-pack telemetry into an existing pack list while.

    Overlay present fields for an explicitly matched serial. Anonymous rows are
    matched only when their complete values are equal, with multiplicity preserved;
    a serial may bind an anonymous slot only with explicit confirmation.
    Non-dict and None entries from the prior list are ignored. Values already
    learned from any transport remain available when a later partial frame omits
    them. Separate list containers do not establish a physical position.

    Every dict entry from the prior list is retained. The battery-pack *shape*
    predicate (``looks_like_battery_pack``) is intentionally NOT applied here: it is
    the discovery-time filter, not a merge-time filter. A pack that carries only
    ``batNum``/``batSoc``/``batTemp`` (no ``deviceSn``) is still a real pack and must
    survive a later MQTT frame that adds serial-numbered packs — otherwise the
    serial-numbered frame silently replaces the serial-less packs and the lifetime
    statistic gets reassigned to the wrong physical pack (2026-09-22).

    Returns:
        Merged list of battery pack dictionaries.
    """
    merged = [item for item in _dict_list(current) if isinstance(item, dict)]
    identity_keys = (FIELD_DEVICE_SN, FIELD_DEV_SN, FIELD_SN)
    old_serials = [battery_pack_serial(item) for item in merged]
    new_serials = [battery_pack_serial(item) for item in updates]
    old_counts = Counter(old_serials)
    new_counts = Counter(new_serials)
    ambiguous = {
        serial
        for serial in old_counts.keys() | new_counts.keys()
        if serial is not None and (old_counts[serial] > 1 or new_counts[serial] > 1)
    }
    index_by_sn = {
        serial: index
        for index, serial in enumerate(old_serials)
        if serial is not None and serial not in ambiguous
    }
    unmatched_anonymous = [
        index for index, serial in enumerate(old_serials) if serial is None
    ]
    unmatched_ambiguous = [
        index for index, serial in enumerate(old_serials) if serial in ambiguous
    ]

    positional_options = _PositionalPackMatchOptions(
        identity_keys=identity_keys,
        updates_count=len(updates),
        ambiguous=ambiguous,
        confirm_serial_slot=confirm_serial_slot,
    )

    for update_idx, raw_update in enumerate(updates):
        update = _battery_pack_merge_update(raw_update)
        if not update:
            continue
        sn = battery_pack_serial(update)
        target_idx = index_by_sn.get(sn) if sn is not None else None
        if sn is None or sn in ambiguous:
            target_idx = _matching_anonymous_pack_index(
                merged,
                unmatched_anonymous if sn is None else unmatched_ambiguous,
                update,
                identity_keys,
                sn,
            )
        if allow_positional_matching and target_idx is None:
            target_idx = _positional_pack_target_index(
                merged,
                update_idx,
                update,
                positional_options,
            )

        if select_update is not None:
            update = _battery_pack_merge_update(
                select_update(
                    merged[target_idx] if target_idx is not None else {},
                    raw_update,
                    target_idx if target_idx is not None else len(merged),
                )
            )
            if not update:
                continue
        # Keep explicit null fields on accepted rows without erasing a prior value.
        previous = merged[target_idx] if target_idx is not None else {}
        update.update({
            key: None
            for key, value in raw_update.items()
            if value is None
            and key not in identity_keys
            and key not in previous
            and key not in update
        })
        if target_idx is None:
            merged.append(dict(update))
            target_idx = len(merged) - 1
        else:
            merged[target_idx] = merge_dict_values(previous, update)
        if sn is not None and sn not in ambiguous:
            index_by_sn[sn] = target_idx

    # Prune devType-only "request selectors" (devType=1, no serial, no
    # telemetry) shadowed by an adjacent serial-bearing pack with telemetry.
    return [
        item
        for idx, item in enumerate(merged)
        if not _is_shadowed_pack_selector(merged, idx)
    ]


def _concurrent_battery_pack_changes(
    previous: object, updates: list[dict[str, Any]]
) -> list[dict[str, object]]:
    """Extract concurrent changes without assigning anonymous rows by position."""
    changes: list[dict[str, object]] = []
    unmatched = [
        pack for pack in _dict_list(previous) if battery_pack_serial(pack) is None
    ]

    def collect(
        prior: dict[str, object],
        update: dict[str, object],
        _target_index: int,
    ) -> dict[str, object]:
        if battery_pack_serial(update) is None:
            match = next(
                (
                    index
                    for index, item in enumerate(unmatched)
                    if _raw_values_equal(item, update)
                ),
                None,
            )
            if match is not None:
                unmatched.pop(match)
                changes.append({})
                return update
        change = changed_dict_values(prior, update, exact_types=True)
        identity: dict[str, object] = {
            key: update[key]
            for key in (FIELD_DEVICE_SN, FIELD_DEV_SN, FIELD_SN)
            if key in update
        }
        changes.append({**identity, **change} if change else {})
        return update

    merge_battery_pack_lists(
        previous, updates, allow_positional_matching=False, select_update=collect
    )
    return changes


# ---------------------------------------------------------------------------
# Subdevice list merging
# ---------------------------------------------------------------------------


def merge_subdevice_lists_by_sn(
    current: object,
    updates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Merge a list of subdevice telemetry entries with incoming updates, matching by.

    device serial number when available.

    This returns a new list of subdevice dicts produced by:
    - copying dict items from `current` (non-dict entries are ignored),
    - removing keys with `None` values from each update before applying,
    - attempting to match each update to an existing item by serial number (checked in
    order: `deviceSn`, `devSn`, `sn`),
    - using the update's positional index only when it has no serial identity,
    - appending the update as a new item when neither a serial match nor a positional
    fallback is available,
    - overlaying update keys onto the matched item (existing keys are preserved when
    not present in the update).

    Parameters:
        current: Prior list-like state (may be None); only dict items are considered
        and copied.
        updates: Sequence of update dicts to merge; update keys with value `None` are
        ignored.

    Returns:
        list[dict[str, Any]]: The merged list of subdevice dictionaries.
    """
    merged = _dict_list(current)
    index_by_sn: dict[str, int] = {}
    for idx, item in enumerate(merged):
        if _has_invalid_subdevice_id(item):
            continue
        if (sn := subdevice_serial(item)) is not None:
            index_by_sn[sn] = idx

    for update_idx, raw_update in enumerate(updates):
        if (
            not raw_update
            or _has_invalid_subdevice_serial(raw_update)
            or _has_invalid_subdevice_id(raw_update)
        ):
            continue
        update = {key: value for key, value in raw_update.items() if value is not None}
        sn = subdevice_serial(update)
        target_idx = index_by_sn.get(sn) if sn is not None else None
        if (
            target_idx is None
            and sn is None
            and update_idx < len(merged)
            and not _has_invalid_subdevice_serial(merged[update_idx])
            and not _has_invalid_subdevice_id(merged[update_idx])
        ):
            target_idx = update_idx

        if target_idx is None:
            merged.append(dict(update))
            if sn is not None:
                index_by_sn[sn] = len(merged) - 1
        else:
            merged[target_idx] = merge_dict_values(merged[target_idx], update)
            if sn is not None:
                index_by_sn[sn] = target_idx
    return merged


def merge_subdevice_list_by_identity(
    current: object,
    update: dict[str, Any],
    *,
    fill_only: bool = False,
) -> list[dict[str, Any]]:
    """Merge Shelly Cloud accessory data by stable identity values and return an.

    updated list.

    Builds a working copy of `current` (ignoring non-dict entries), removes keys with
    `None` from `update`, and computes identity values via `subdevice_identity_values`.
    If any existing item's identity set intersects the update's identity set, overlays
    the update onto that first matching item (using `merge_dict_values`) and returns
    the merged list. If no match is found and the cleaned update has identity values,
    appends the cleaned update. Non-dict entries in `current` are ignored in the
    resulting list.

    Parameters:
        current (Any): Prior list-like state; dict items are copied and non-dict
        entries are ignored.
        update (dict[str, Any]): Incoming accessory data; keys with `None` are
        discarded before matching.

    Returns:
        list[dict[str, Any]]: New list of subdevice dicts with the update merged into a
        matching identity entry or appended when no match exists.
    """
    cleaned = {key: value for key, value in update.items() if value is not None}
    merged = _dict_list(current)
    update_ids = subdevice_identity_values(cleaned)
    for idx, item in enumerate(merged):
        if update_ids and update_ids & subdevice_identity_values(item):
            merged[idx] = (
                merge_missing_dict_values(item, cleaned)
                if fill_only
                else merge_dict_values(item, cleaned)
            )
            return merged
    if cleaned and update_ids:
        merged.append(cleaned)
    return merged


def merge_smart_plug_lists(
    current: object,
    updates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Merge incremental smart-plug telemetry entries using device serial numbers to.

    align updates with existing entries.

    Parameters:
        current (Any): Prior list-like smart-plug state; may be None and may contain
        non-dict items — only dictionary items are considered when merging.
        updates (list[dict[str, Any]]): List of update dictionaries; update entries
        have `None` values removed before being merged.

    Returns:
        list[dict[str, Any]]: Merged list of smart-plug dictionaries where updates are
        overlaid onto existing entries matched by device serial number
        (`deviceSn`/`devSn`/`sn`), or by position only when the update has no serial.
    """
    return merge_subdevice_lists_by_sn(current, updates)


def merge_circuits(
    current: object,
    updates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Merge incremental circuit breaker telemetry using idx to align updates."""
    return _merge_subdevice_lists_by_fn(current, updates, circuit_id)


def merge_sub_devices(
    current: object,
    updates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Merge generic sub-device telemetry using serial numbers to align updates."""
    return _merge_subdevice_lists_by_fn(current, updates, sub_device_serial)


def _merge_subdevice_lists_by_fn(
    current: object,
    updates: list[dict[str, Any]],
    serial_fn: Callable[[object], str | None],
) -> list[dict[str, Any]]:
    """Merge a list of subdevice telemetry entries with incoming updates, matching by.

    identity extracted via serial_fn.
    """
    merged = _dict_list(current)
    index_by_sn: dict[str, int] = {}
    for idx, item in enumerate(merged):
        if _has_invalid_subdevice_serial(item) or (
            serial_fn is sub_device_serial and _has_invalid_subdevice_id(item)
        ):
            continue
        sn = serial_fn(item)
        if sn:
            index_by_sn[str(sn)] = idx

    for update_idx, raw_update in enumerate(updates):
        if (
            not raw_update
            or _has_invalid_subdevice_serial(raw_update)
            or (
                serial_fn is sub_device_serial and _has_invalid_subdevice_id(raw_update)
            )
        ):
            continue
        update = {key: value for key, value in raw_update.items() if value is not None}
        sn = serial_fn(update)
        target_idx = index_by_sn.get(str(sn)) if sn else None
        if (
            target_idx is None  # ruff: ignore[too-many-boolean-expressions]
            and sn is None
            and update_idx < len(merged)
            and not _has_invalid_subdevice_serial(merged[update_idx])
            and (
                serial_fn is not sub_device_serial
                or not _has_invalid_subdevice_id(merged[update_idx])
            )
        ):
            target_idx = update_idx

        if target_idx is None:
            merged.append(dict(update))
            if sn:
                index_by_sn[str(sn)] = len(merged) - 1
        else:
            merged[target_idx] = merge_dict_values(merged[target_idx], update)
            if sn:
                index_by_sn[str(sn)] = target_idx
    return merged


def resolve_device_id_from_payload(payload: dict[str, Any]) -> str | None:
    """Extract the parent device identifier from a payload slice.

    Searches top-level keys in order: "deviceId", "device_id", then "id". If none are
    present or valid, and the payload contains a "properties" dict, searches "deviceId"
    and "device_id" there. Accepts string or integer values and returns the value as a
    stripped string.

    Returns:
        device_id (str | None): The extracted device identifier as a stripped string if
        found, `None` otherwise.
    """
    for key in ("deviceId", "device_id", "id"):
        value = payload.get(key)
        if (
            isinstance(value, str | int)
            and not isinstance(value, bool)
            and str(value).strip()
        ):
            return str(value).strip()
    props = payload.get("properties")
    if isinstance(props, dict):
        for key in ("deviceId", "device_id"):
            value = props.get(key)
            if (
                isinstance(value, str | int)
                and not isinstance(value, bool)
                and str(value).strip()
            ):
                return str(value).strip()
    return None


# ---------------------------------------------------------------------------
# OTA metadata merging
# ---------------------------------------------------------------------------


_BATTERY_PACK_OTA_FIELDS = (
    FIELD_VERSION,
    FIELD_CURRENT_VERSION,
    FIELD_IS_FIRMWARE_UPGRADE,
    FIELD_TARGET_VERSION,
    FIELD_TARGET_MODULE_VERSION,
    FIELD_UPDATE_STATUS,
    FIELD_UPDATE_CONTENT,
    FIELD_UPGRADE_TYPE,
)


def _copy_pack_for_ota(pack: dict[str, Any]) -> dict[str, Any]:
    """Keep mutable OTA fields separate across in-flight snapshots."""
    return {
        **pack,
        **{
            key: copy.deepcopy(pack[key])
            for key in _BATTERY_PACK_OTA_FIELDS
            if key in pack
        },
    }


def merge_pack_ota(pack: dict[str, Any], ota: dict[str, Any]) -> None:
    """Merge OTA metadata into a battery pack dictionary in place.

    Copies the OTA version (from `currentVersion` or `version`) into both `version` and
    `currentVersion` on the pack. For each OTA key (isFirmwareUpgrade, targetVersion,
    targetModuleVersion, updateStatus, updateContent, upgradeType), if the key exists
    in `ota` and its value is not None, writes that key/value into `pack`.

    Parameters:
        pack (dict[str, Any]): Battery pack object to update in-place.
        ota (dict[str, Any]): OTA metadata source whose fields will be merged into
        `pack`.
    """
    current_version = ota.get(FIELD_CURRENT_VERSION) or ota.get(FIELD_VERSION)
    if current_version is not None:
        pack[FIELD_VERSION] = copy.deepcopy(current_version)
        pack[FIELD_CURRENT_VERSION] = copy.deepcopy(current_version)
    for key in (
        FIELD_IS_FIRMWARE_UPGRADE,
        FIELD_TARGET_VERSION,
        FIELD_TARGET_MODULE_VERSION,
        FIELD_UPDATE_STATUS,
        FIELD_UPDATE_CONTENT,
        FIELD_UPGRADE_TYPE,
    ):
        if key in ota and ota.get(key) is not None:
            pack[key] = copy.deepcopy(ota[key])


def _pack_ota_cache_matches(
    pack: dict[str, Any],
    ota: dict[str, Any],
    basis: tuple[float, Any] | None,
    timestamp: float,
) -> bool:
    """Accept cached OTA fields only for their compatible pack snapshot."""
    fields: dict[str, Any] = {}
    merge_pack_ota(fields, ota)
    if not fields:
        return True
    return bool(
        basis
        and basis[0] == timestamp
        and isinstance(basis[1], dict)
        and all(
            key not in pack
            or pack.get(key) == basis[1].get(key)
            or pack.get(key) == value
            for key, value in fields.items()
        )
    )


def _battery_pack_ota_changed_updates(
    previous_packs: list[dict[str, Any]],
    working_packs: list[dict[str, Any]],
    live_packs: list[dict[str, Any]],
    ota_cache: dict[str, tuple[float, Any]],
    completed_serial: str,
) -> list[dict[str, Any]]:
    """Return changes for the completed request that preserve newer fields."""
    updates = []
    for previous, updated in zip(previous_packs, working_packs, strict=True):
        serial = battery_pack_serial(previous)
        if serial != completed_serial or _has_invalid_subdevice_serial(previous):
            continue
        previous_matches = [
            pack for pack in previous_packs if battery_pack_serial(pack) == serial
        ]
        live_matches = [
            pack for pack in live_packs if battery_pack_serial(pack) == serial
        ]
        if len(previous_matches) != 1 or len(live_matches) != 1:
            ota_cache.pop(f"pack_ota:{serial}", None)
            ota_cache.pop(f"pack_ota_basis:{serial}", None)
            continue
        live = live_matches[0]
        cached = ota_cache.get(f"pack_ota:{serial}")
        cached_fields: dict[str, Any] = {}
        if cached and isinstance(cached[1], dict):
            merge_pack_ota(cached_fields, cached[1])
        if any(live.get(key) != previous.get(key) for key in cached_fields):
            # Keep the request's original basis and TTL. Discarding them
            # schedules the same stale OTA response on the next HTTP poll.
            continue
        delta = {
            key: copy.deepcopy(value)
            for key, value in updated.items()
            if (key not in previous or previous[key] != value)
            and live.get(key) == previous.get(key)
        }
        if delta:
            updates.append({FIELD_DEVICE_SN: serial, **delta})
    return updates


def merge_battery_pack_ota_lists(
    current: object,
    ota_updates: list[dict[str, Any]],
) -> list[Any]:
    """Overlay serial-owned OTA fields while keeping every existing pack slot."""
    merged = (
        [dict(item) if isinstance(item, dict) else item for item in current]
        if isinstance(current, list | tuple)
        else []
    )
    index_by_sn: dict[str, int | None] = {}
    for idx, item in enumerate(merged):
        if isinstance(item, dict) and (sn := battery_pack_serial(item)) is not None:
            index_by_sn[sn] = None if sn in index_by_sn else idx

    for raw_update in ota_updates:
        if _has_invalid_subdevice_serial(raw_update):
            continue
        sn = battery_pack_serial(raw_update)
        target_idx = index_by_sn.get(sn) if sn is not None else None
        if target_idx is None:
            continue
        target = merged[target_idx]
        if not isinstance(target, dict) or _has_invalid_subdevice_serial(target):
            continue
        for key in _BATTERY_PACK_OTA_FIELDS:
            if key in raw_update and raw_update.get(key) is not None:
                target[key] = copy.deepcopy(raw_update[key])
    return merged


# ---------------------------------------------------------------------------
# Misc pure helpers
# ---------------------------------------------------------------------------


def app_period_section(prefix: str, date_type: str) -> str:
    """Build the normalized ``<prefix>_<date_type>`` app-period key."""
    return f"{prefix}_{date_type}"


def shelly_cloud_api_device_id(item: dict[str, Any]) -> str | None:
    """Determine the native Shelly Cloud device identifier for a device payload.

    Returns the Shelly-native device id used by Shelly Cloud realtime/control APIs when
    the provided item represents a Shelly Cloud-related payload (e.g., identified as
    Shelly, marked as cloud, or containing host/device code). Selection preference:
    - a non-empty, non-numeric deviceId when present,
    - otherwise a subdevice serial-based id if available,
    - otherwise a generic subdevice id.

    Returns:
        str: Device id suitable for Shelly Cloud APIs, or `None` if the item does not
        indicate a Shelly Cloud payload.
    """
    if _has_invalid_subdevice_serial(item) or _has_invalid_subdevice_id(item):
        return None
    scan_name = str(item.get(FIELD_SCAN_NAME) or "").lower()
    is_shelly = scan_name.startswith("shelly")
    if not (
        is_shelly
        or str(item.get(FIELD_IS_CLOUD)).lower() in {"1", "true"}
        or item.get(FIELD_HOST) is not None
        or item.get(FIELD_DEVICE_CODE) is not None
    ):
        return None

    direct_id = item.get("deviceId")
    if is_shelly:
        # System-list accessories use a numeric Jackery accessory id in
        # deviceId, while Shelly Cloud realtime/control expects the native
        # Shelly device id (`5c...`). The app-linked boundDevices payload
        # exposes that id either as deviceId or, in system-list, deviceSn.
        if direct_id not in {None, ""} and not str(direct_id).isdecimal():
            return str(direct_id)
        serial = subdevice_serial(item)
        if serial:
            return serial

    return subdevice_id(item)


def normalize_shelly_cloud_payload(
    source: Mapping[str, Any],
) -> dict[str, Any]:
    """Normalize and flatten a Shelly Cloud DeviceItem or RealData payload into.

    subdevice fields.

    Creates a shallow copy of all keys from `source` whose values are not None, merges
    any dictionary found under FIELD_POWER_BODY into the top-level result, and sets
    several fallback fields when their canonical counterparts are present:
    - copies FIELD_SWITCH into FIELD_SWITCH_STATE and FIELD_SYS_SWITCH if those keys
    are missing,
    - copies FIELD_OP -> FIELD_OUT_PW, FIELD_IP -> FIELD_IN_PW, and FIELD_ONLINE ->
    FIELD_ONLINE_STATUS when missing.
    If FIELD_SCAN_NAME is present and (lowercased) matches an entry in
    SUBDEVICE_SCAN_NAME_DEV_TYPES, rewrites FIELD_SCAN_NAME to the lowercased value and
    sets FIELD_DEV_TYPE from the mapping when missing.

    Parameters:
        source (Mapping[str, Any]): Original Shelly Cloud payload (DeviceItem or
        RealData).

    Returns:
        dict[str, Any]: A normalized, flattened dictionary suitable for subdevice
        merging.
    """
    normalized = {key: value for key, value in source.items() if value is not None}
    power_body = normalized.get(FIELD_POWER_BODY)
    if isinstance(power_body, dict):
        normalized = merge_dict_values(normalized, power_body)
    temperature = _shelly_temperature_c(normalized)
    if temperature is not None:
        normalized[FIELD_CT_TEMPERATURE_C] = temperature
    if FIELD_SWITCH in normalized:
        switch_state = normalized[FIELD_SWITCH]
        normalized.setdefault(FIELD_SWITCH_STATE, switch_state)
        normalized.setdefault(FIELD_SYS_SWITCH, switch_state)
    if FIELD_OP in normalized:
        normalized.setdefault(FIELD_OUT_PW, normalized[FIELD_OP])
    # ``ip`` is overloaded by Jackery's portable PowerBody (input power) and
    # Shelly Cloud device metadata (IPv4/IPv6 address).  Never copy an address
    # string into ``inPw`` — that produced states such as
    # ``inPw: "192.168.2.76"`` in the CT payload.
    if FIELD_IP in normalized and safe_float(normalized[FIELD_IP]) is not None:
        normalized.setdefault(FIELD_IN_PW, normalized[FIELD_IP])
    if FIELD_ONLINE in normalized:
        normalized.setdefault(FIELD_ONLINE_STATUS, normalized[FIELD_ONLINE])
    scan_name = str(normalized.get(FIELD_SCAN_NAME) or "").lower()
    scan_type = _subdevice_type_from_scan_name(scan_name)
    if scan_name and scan_type is not None:
        normalized[FIELD_SCAN_NAME] = scan_name
        normalized.setdefault(
            FIELD_DEV_TYPE,
            subdevice_dev_type(normalized),
        )
    return normalized


def shelly_cloud_device_matches_entry(
    entry: dict[str, Any],
    shelly_device: Mapping[str, Any],
) -> bool:
    """Determine whether the given Shelly Cloud device belongs to the provided entry.

    Checks for any overlap between the set of subdevice identity values derived from
    `shelly_device` and the identity sets of the entry's subdevice candidates.

    Returns:
        `True` if any subdevice identity intersects, `False` otherwise.
    """
    shelly_ids = subdevice_identity_values(shelly_device)
    if not shelly_ids:
        return False
    return any(
        shelly_ids & subdevice_identity_values(candidate)
        for candidate in entry_subdevice_candidates(entry)
    )


