def _local_mqtt_rearm_cooldown(previous: tuple[Any, ...]) -> float:
    """Back off repeated confirmed writes during one stale-traffic episode."""
    raw_attempts = previous[3] if len(previous) > 3 else 1  # ruff: ignore[magic-value-comparison]
    attempts: int = (
        raw_attempts if type(raw_attempts) is int and raw_attempts > 0 else 1
    )
    return float(
        min(
            _LOCAL_MQTT_BRIDGE_REARM_MAX_COOLDOWN_SEC,
            _LOCAL_MQTT_BRIDGE_REARM_COOLDOWN_SEC * (2 ** min(attempts - 1, 2)),
        )
    )


