def battery_pack_source_lists(source: object) -> list[tuple[str, list[Any]]]:
    """Collect the recognized, nonempty pack-list containers in one payload."""

    def collect(obj: object, key: str) -> list[list[Any]]:
        """Visit every nested occurrence, including sibling containers."""
        found: list[list[Any]] = []
        if isinstance(obj, dict):
            if isinstance(value := obj.get(key), list) and value:
                found.append(value)
            for nested in obj.values():
                found.extend(collect(nested, key))
        elif isinstance(obj, list):
            for nested in obj:
                found.extend(collect(nested, key))
        return found

    return [
        (key, packs)
        for key in (
            FIELD_BATTERY_PACKS,
            FIELD_BATTERY_PACK,
            FIELD_BATTERY_PACK_LIST,
            FIELD_BATTERY_PACKS_UNDERSCORE,
            FIELD_BATTERIES,
            FIELD_PACK_LIST,
            FIELD_SUB_DEVICES,
            FIELD_SUB_DEVICE,
        )
        for packs in collect(source, key)
    ]


def _merge_source_receipts(
    current: dict[str, Any], incoming: dict[str, Any], identity: str
) -> dict[str, Any]:
    """Join raw field receipts by arrival while retaining their original times."""

    def receipt_state(receipt: dict[str, Any]) -> IngestResult:
        observations = {
            tuple(field["path"]): field for field in receipt["field_observations"]
        }
        provenance: dict[ProvenanceKey, FieldProvenance] = {}

        def collect(value: object, path: tuple[str, ...]) -> FieldProvenance | None:
            if isinstance(value, dict) and value:
                children = [
                    collect(child, (*path, name)) for name, child in value.items()
                ]
                source = max(
                    (child for child in children if child is not None),
                    key=lambda child: child.received_at_monotonic,
                    default=None,
                )
            else:
                field = next(
                    (
                        observations[path[:length]]
                        for length in range(len(path), 0, -1)
                        if path[:length] in observations
                    ),
                    None,
                )
                source = (
                    FieldProvenance(
                        source=TransportSource(receipt["source"]),
                        section=receipt["section"],
                        observed_at=None,
                        received_at_monotonic=field["received_at_monotonic"],
                    )
                    if field is not None
                    else None
                )
            if source is not None:
                provenance[path[0] if len(path) == 1 else path] = source
            return source

        for name, value in receipt["values"].items():
            collect(value, (name,))
        return IngestResult(
            payload=receipt["values"],
            provenance=provenance,
            accepted_fields=frozenset(),
        )

    selected = merge_selected_state(
        receipt_state(current), receipt_state(incoming), freshness_window_seconds=0
    )
    fields: dict[tuple[str, ...], dict[str, Any]] = {}
    for receipt in (current, incoming):
        for field in receipt["field_observations"]:
            path = tuple(field["path"])
            previous = fields.get(path)
            if previous is None or (
                field["received_at_monotonic"] > previous["received_at_monotonic"]
            ):
                fields[path] = copy.deepcopy(field)
    latest = (
        incoming
        if incoming["received_at_monotonic"] > current["received_at_monotonic"]
        else current
    )
    merged = {
        **copy.deepcopy(latest),
        "identity": identity,
        "values": selected.payload,
        "field_observations": list(fields.values()),
    }
    frames: dict[str, tuple[float, dict[str, object]]] = {}
    for receipt in (current, incoming):
        for cmd, frame in receipt.get("original_frames", {}).items():
            received_at = frame.get(
                "received_at_monotonic", receipt["received_at_monotonic"]
            )
            previous_frame = frames.get(cmd)
            if previous_frame is None or received_at > previous_frame[0]:
                frames[cmd] = (received_at, copy.deepcopy(frame))
    if frames:
        merged["original_frames"] = {
            cmd: frame for cmd, (_received_at, frame) in frames.items()
        }
    original_receipts = [
        receipt for receipt in (current, incoming) if "original_payload" in receipt
    ]
    if original_receipts:
        newest = max(
            original_receipts,
            key=lambda receipt: receipt.get(
                "original_payload_received_at_monotonic",
                receipt["received_at_monotonic"],
            ),
        )
        merged["original_payload"] = copy.deepcopy(newest["original_payload"])
        merged["original_payload_received_at_monotonic"] = newest.get(
            "original_payload_received_at_monotonic", newest["received_at_monotonic"]
        )
    return merged


def ct_serial_key(item: object) -> str | None:
    """Return a CT serial normalized across Jackery and Shelly spellings."""
    if not isinstance(item, dict):
        return None
    serial = subdevice_serial(item)
    if serial is None:
        return None
    return serial.replace(":", "").replace("-", "").casefold()


def _ct_l2_serial(item: object) -> str | None:
    """Require one valid, unambiguous serial for an L2-only CT observation."""
    if not isinstance(item, Mapping):
        return None
    serials: set[str] = set()
    for field in (FIELD_DEVICE_SN, FIELD_DEV_SN, FIELD_SN):
        value = item.get(field)
        if value is None:
            continue
        if not isinstance(value, str):
            return None
        if not value:
            continue
        if value != value.strip() or not value.isprintable():
            return None
        normalized = value.replace(":", "").replace("-", "").casefold()
        if not normalized:
            return None
        serials.add(normalized)
    return next(iter(serials)) if len(serials) == 1 else None


def _merge_ct_l2_by_serial(
    current: object, update: dict[str, Any]
) -> list[dict[str, Any]]:
    """Merge L2 meter rows only when their validated serials match."""
    rows = (
        [dict(item) for item in current if isinstance(item, dict)]
        if isinstance(current, list)
        else []
    )
    serial = _ct_l2_serial(update)
    if serial is None:
        return rows
    for index, item in enumerate(rows):
        if _ct_l2_serial(item) == serial:
            rows[index] = merge_present_dict_values(item, update)
            return rows
    rows.append(dict(update))
    return rows


def ct_identity_changed(current: object, incoming: object) -> bool:
    """Return True only when two serial-bearing CT records are different devices.

    A record without a serial cannot prove a device change, so it keeps the
    established merge path (BLE frames often omit ``deviceSn``).
    """
    old = ct_serial_key(current)
    new = ct_serial_key(incoming)
    return old is not None and new is not None and old != new


class JackerySolarVaultCoordinator(  # ruff: ignore[too-many-public-methods]
    JackeryAiemsManagerMixin,
    JackeryRecorderReconcileMixin,
    JackeryStatisticsEngineMixin,
    JackeryCommandDispatcherMixin,
    JackeryBleEventAdapterMixin,
    DataUpdateCoordinator[dict[str, dict[str, Any]]],
):
    """Polls all known Jackery devices."""

    _cloud_ota_starting_devices: set[str]

    _PRICE_OVERRIDE_TTL_SEC = 30
    _PROPERTY_OVERRIDE_TTL_SEC = 15

    _CT_METER_KEYS = CT_METER_KEYS
    _SUBDEVICE_HINT_KEYS = SUBDEVICE_HINT_KEYS
    _SUBDEVICE_ONLY_PROPERTY_KEYS = SUBDEVICE_ONLY_PROPERTY_KEYS
    _SUBDEVICE_MAIN_MIRROR_KEYS = SUBDEVICE_MAIN_MIRROR_KEYS
    _SUBDEVICE_DEV_TYPE_STRINGS = NON_BATTERY_SUBDEVICE_TYPES | {
        str(SUBDEVICE_DEV_TYPE_BATTERY_PACK),
    }
    _SYSTEM_INFO_KEYS = SYSTEM_INFO_KEYS
    _BATTERY_PACK_HINT_KEYS = BATTERY_PACK_HINT_KEYS
    _MAIN_PROPERTY_ALIAS_PAIRS = MAIN_PROPERTY_ALIAS_PAIRS
    _BATTERY_PACK_LIVE_KEYS = frozenset({FIELD_BAT_SOC, FIELD_CELL_TEMP})
    #: pv family tracked by the per-key stale marker (F7 2026-07-03):
    #: scalar PV power plus the nested pv1..pv4 MPPT objects.
    _PV_PROPERTY_KEYS = frozenset({
        FIELD_PV_PW,
        FIELD_PV1,
        FIELD_PV2,
        FIELD_PV3,
        FIELD_PV4,
    })
    _DEVICE_STATISTIC_LIVE_KEYS = frozenset({
        APP_DEVICE_STAT_PV_ENERGY,
        APP_DEVICE_STAT_BATTERY_CHARGE,
        APP_DEVICE_STAT_BATTERY_DISCHARGE,
        APP_DEVICE_STAT_ONGRID_INPUT,
        APP_DEVICE_STAT_ONGRID_OUTPUT,
        APP_DEVICE_STAT_BATTERY_TO_GRID,
        APP_DEVICE_STAT_PV_TO_BATTERY,
        APP_DEVICE_STAT_PV_TO_ONGRID,
        APP_DEVICE_STAT_ONGRID_TO_BATTERY,
        APP_DEVICE_STAT_EPS_INPUT,
        APP_DEVICE_STAT_EPS_OUTPUT,
    })
    _MAIN_LIVE_PROPERTY_KEYS = frozenset({
        *LOCAL_DAILY_LIFETIME_METRICS,
        "ac1",
        "ac2",
        "fz",
        # Sanitization synchronizes both sides of these App/property aliases.
        # Every alias must stay in the same live-ingest tier; otherwise fields
        # such as ``batterySoc`` bypass timestamp/freshness protection as if
        # they were static configuration.
        *{key for alias_pair in _LIVE_PROPERTY_ALIAS_PAIRS for key in alias_pair},
        FIELD_SOC,
        FIELD_BAT_STATE,
        FIELD_ONGRID_STAT,
        FIELD_SYS_TOTAL_PV_PW,
        FIELD_BLE_BOX_MAINS_POWER,
        FIELD_BLE_BOX_HOUSE_POWER,
        FIELD_BLE_PORTABLE_INPUT_POWER,
        FIELD_BLE_PORTABLE_OUTPUT_POWER,
        FIELD_OP,
        FIELD_BAT_SOC,
        FIELD_IS_PACK_CONNECT,
        FIELD_CELL_TEMP,
        FIELD_CHARGE_PLAN_PW,
        FIELD_ENERGY_PLAN_PW,
        FIELD_PV_PW,
        FIELD_PV1,
        FIELD_PV2,
        FIELD_PV3,
        FIELD_PV4,
        FIELD_BAT_IN_PW,
        FIELD_BAT_OUT_PW,
        FIELD_STACK_IN_PW,
        FIELD_STACK_OUT_PW,
        FIELD_GRID_IN_PW,
        FIELD_GRID_OUT_PW,
        FIELD_IN_GRID_SIDE_PW,
        FIELD_OUT_GRID_SIDE_PW,
        FIELD_IN_ONGRID_PW,
        FIELD_OUT_ONGRID_PW,
        FIELD_OTHER_LOAD_PW,
        FIELD_SW_EPS_IN_PW,
        FIELD_SW_EPS_OUT_PW,
        FIELD_SW_EPS,
        FIELD_SW_EPS_STATE,
        FIELD_WORK_MODEL,
    })
    # A Local-MQTT measurement can be instantaneous, lifetime, or periodic.
    # Recognize each documented field without discarding counter-only frames.
    # Freshness is still anchored to the observation timestamp, never to a
    # synthetic value or to the mere presence of a broker connection.
    _LOCAL_MQTT_COUNTER_ONLY_FIELDS = frozenset({
        *LOCAL_DAILY_LIFETIME_METRICS,
        FIELD_IN_EGY,
        FIELD_OUT_EGY,
        FIELD_TODAY_ENERGY,
        FIELD_TOTAL_ENERGY,
        FIELD_CHARGING_ENERGY,
        FIELD_DISCHARGING_ENERGY,
        *(key for key in CT_METER_KEYS if key.endswith("Egy")),
    })
    _LOCAL_MQTT_TELEMETRY_FIELDS = frozenset({
        *_MAIN_LIVE_PROPERTY_KEYS,
        *CT_METER_KEYS,
        *_LOCAL_MQTT_COUNTER_ONLY_FIELDS,
        *_BATTERY_PACK_LIVE_KEYS,
        FIELD_COMM_STATE,
        FIELD_IN_PW,
        FIELD_OUT_PW,
        # Dated HTTP/App period names can also arrive as decoded Local MQTT.
        "totalCharge",
        "totalDischarge",
        "totalSolarEnergy",
        "totalInGridEnergy",
        "totalOutGridEnergy",
        "totalInCtEnergy",
        "totalOutCtEnergy",
        "totalInEpsEnergy",
        "totalOutEpsEnergy",
        "totalChgEgy",
        "totalDisChgEgy",
        "totalHomeEgy",
        "totalGeneration",
        "todayLoad",
        "todayGeneration",
    })
    # Counter-only type-23 bursts are valid telemetry, but they do not prove
    # that the missing operating/status stream recovered. Keep the re-arm
    # backoff across those bursts instead of writing 3046 every few minutes.
    _LOCAL_MQTT_REARM_RECOVERY_FIELDS = frozenset(
        (_MAIN_LIVE_PROPERTY_KEYS | CT_METER_KEYS | _BATTERY_PACK_LIVE_KEYS)
        - _LOCAL_MQTT_COUNTER_ONLY_FIELDS
    )
    # The App renders these instantaneous power channels from CombineData.
    # CombineData/SystemBody names complete-stack power batInPw/batOutPw.
    # normalize_live_property_payload rewrites those packet-local names to the
    # stack fields before they reach this set. DeviceProperty/HTTP batInPw and
    # batOutPw therefore remain the independent main-battery measurements.
    _COMBINE_CANONICAL_PROPERTY_KEYS = frozenset({
        FIELD_STACK_IN_PW,
        FIELD_STACK_OUT_PW,
        FIELD_PV_PW,
        FIELD_GRID_IN_PW,
        FIELD_GRID_OUT_PW,
        FIELD_IN_ONGRID_PW,
        FIELD_OUT_ONGRID_PW,
        FIELD_IN_GRID_SIDE_PW,
        FIELD_OUT_GRID_SIDE_PW,
        FIELD_OTHER_LOAD_PW,
    })
    # devType -> coordinator live bucket holding that accessory's telemetry.
    # AGENTS.md HTTP-primary: the shadow fallback fills these buckets when the
    # supplemental Layer-5 push is absent, stale, or missing HTTP-only fields.
    _SHADOW_DEV_TYPE_BUCKETS: ClassVar[dict[int, str]] = {
        SUBDEVICE_DEV_TYPE_BATTERY_PACK: PAYLOAD_BATTERY_PACKS,
        SUBDEVICE_DEV_TYPE_COMBO: PAYLOAD_SUBDEVICES,
        SUBDEVICE_DEV_TYPE_CT: PAYLOAD_CT_METER,
        SUBDEVICE_DEV_TYPE_METER_HEAD: PAYLOAD_METER_HEADS,
        SUBDEVICE_DEV_TYPE_SOCKET: PAYLOAD_SMART_PLUGS,
    }
    _DEVICE_YEAR_BACKFILL_STAT_KEYS: ClassVar[dict[str, tuple[str, ...]]] = {
        APP_SECTION_PV_STAT: (
            APP_STAT_TOTAL_SOLAR_ENERGY,
            APP_STAT_PV1_ENERGY,
            APP_STAT_PV2_ENERGY,
            APP_STAT_PV3_ENERGY,
            APP_STAT_PV4_ENERGY,
        ),
        APP_SECTION_BATTERY_STAT: (
            APP_STAT_TOTAL_CHARGE,
            APP_STAT_TOTAL_DISCHARGE,
        ),
        APP_SECTION_HOME_STAT: (
            APP_STAT_TOTAL_IN_GRID_ENERGY,
            APP_STAT_TOTAL_OUT_GRID_ENERGY,
        ),
        APP_SECTION_CT_STAT: (
            APP_STAT_TOTAL_CT_INPUT_ENERGY,
            APP_STAT_TOTAL_CT_OUTPUT_ENERGY,
        ),
        APP_SECTION_EPS_STAT: (
            APP_STAT_TOTAL_IN_EPS_ENERGY,
            APP_STAT_TOTAL_OUT_EPS_ENERGY,
        ),
    }
    _SYSTEM_YEAR_BACKFILL_STAT_KEYS: ClassVar[dict[str, tuple[str, ...]]] = {
        APP_SECTION_HOME_TRENDS: (APP_STAT_TOTAL_HOME_ENERGY,),
    }

    def __init__(
        self,
        hass: HomeAssistant,
        entry: ConfigEntry,
        api: JackeryApi,
        update_interval: timedelta,
    ) -> None:
        """Initialise the entity from the coordinator and description."""
        super().__init__(
            hass,
            _LOGGER,
            config_entry=entry,
            name=f"{DOMAIN} ({entry.title})",
            update_interval=update_interval,
        )
        interval_sec = self._init_api_http_state(entry, api, update_interval)

        self._init_cloud_query_state(interval_sec)
        self._init_runtime_task_and_ingest_state()
        self._init_statistics_storage_state(hass, entry)
        self._init_local_transport_state(api)
        self._init_polling_diagnostics_state(hass)

    def _init_api_http_state(
        self,
        entry: ConfigEntry,
        api: JackeryApi,
        update_interval: timedelta,
    ) -> int:
        """Initialize API ownership, HTTP concurrency, and discovery state."""
        self.api = api
        self.api.dev_mode_entry = entry
        self.api.payload_debug_callback = self._schedule_payload_debug_event
        self.api.payload_debug_capture_policy = self._payload_debug_capture_policy
        self.api.auth_rejection_callback = self.record_http_auth_rejection
        self.rejection_metrics = RejectionMetrics()
        self.entry = entry
        self._configured_update_interval = update_interval
        http_parallelism = max(
            1,
            safe_int(
                entry.options.get(
                    CONF_HTTP_MAX_PARALLEL_REQUESTS,
                    DEFAULT_HTTP_MAX_PARALLEL_REQUESTS,
                )
            )
            or DEFAULT_HTTP_MAX_PARALLEL_REQUESTS,
        )
        # One gate covers every Layer-3 call so per-feature concurrency cannot
        # combine into a cloud burst large enough to trigger code 10426.
        self._http_request_semaphore = asyncio.Semaphore(http_parallelism)
        self._slow_http_request_semaphore = (
            asyncio.Semaphore(http_parallelism - 1)
            if http_parallelism > 1
            else self._http_request_semaphore
        )
        self._startup_slow_http_semaphore = asyncio.Semaphore(1)
        interval_sec = max(
            MIN_SCAN_INTERVAL_SEC,
            safe_int(update_interval.total_seconds()) or DEFAULT_SCAN_INTERVAL_SEC,
        )
        self._slow_metrics_interval_sec = max(SLOW_METRICS_INTERVAL_SEC, interval_sec)
        self._historical_metrics_interval_sec = max(
            _HISTORICAL_PERIOD_MIN_INTERVAL_SEC,
            interval_sec,
        )
        self._alarm_http_interval_sec = max(ALARM_HTTP_INTERVAL_SEC, interval_sec)
        self._price_config_interval_sec = max(PRICE_CONFIG_INTERVAL_SEC, interval_sec)
        self._last_discovery_refresh_monotonic: float = float("-inf")
        self._pending_discovery_parent_removals: set[tuple[str, str]] = set()
        self._device_index: dict[str, dict[str, Any]] = {}
        return interval_sec

    def _init_cloud_query_state(self, interval_sec: int) -> None:
        """Initialize slow HTTP caches and independent Cloud MQTT state."""
        self._slow_cache: dict[str, dict[str, tuple[float, Any]]] = {}
        self._cached_date: date | None = None
        self._mqtt: JackeryMqttPushClient | None = None
        self._mqtt_mgr = MqttConnectionManager()
        self._mqtt_session_generation = 0
